const fieldLabel=(value:string)=>typeof document!=='undefined'&&document.documentElement.lang==='en'?(fieldEnglish[value]??value):value
function Field({label,value,unit,onChange,type='number',blankZero=false}:{label:string;value:number|string;unit?:string;onChange:(v:any)=>void;type?:string;blankZero?:boolean}){const displayValue=blankZero&&type==='number'&&value===0?'':value;return <label className="fw-field"><span>{fieldLabel(label)}</span><div><input type={type} value={displayValue} onChange={e=>onChange(type==='number'?Number(e.target.value):e.target.value)}/>{unit&&<small>{fieldLabel(unit)}</small>}</div></label>}
function RowEditor({title,rows,onChange,defaultUnit,blankZero=false}:{title:string;rows:Row[];onChange:(rows:Row[])=>void;defaultUnit:string;blankZero?:boolean}){
 const update=(id:string,key:keyof Row,value:string|number)=>onChange(rows.map(r=>r.id===id?{...r,[key]:value}:r))
 const move=(index:number,direction:number)=>{const next=[...rows],target=index+direction;if(target<0||target>=next.length)return;[next[index],next[target]]=[next[target],next[index]];onChange(next)}
 return <div className="fw-card"><div className="fw-card-head"><h3>{fieldLabel(title)}</h3><button className="secondary-button" onClick={()=>onChange([...rows,makeRow('قلم جدید',defaultUnit)])}><Plus size={15}/> {fieldLabel('افزودن ردیف')}</button></div>
  {rows.map(r=><div className="fw-row" key={r.id}><input aria-label={fieldLabel("عنوان قلم")} value={fieldLabel(r.name)} onChange={e=>update(r.id,'name',e.target.value)}/><input aria-label={fieldLabel("مقدار")} type="number" value={blankZero&&r.quantity===0?'':r.quantity} onChange={e=>update(r.id,'quantity',Number(e.target.value))}/><input aria-label={fieldLabel("واحد")} value={fieldLabel(r.unit)} onChange={e=>update(r.id,'unit',e.target.value)}/><input aria-label={fieldLabel("قیمت واحد")} type="number" value={blankZero&&r.unitPrice===0?'':r.unitPrice} onChange={e=>update(r.id,'unitPrice',Number(e.target.value))}/><input aria-label={fieldLabel("منبع داده")} value={fieldLabel(r.source)} onChange={e=>update(r.id,'source',e.target.value)}/><span className="fw-row-actions"><button className="icon-button" aria-label={fieldLabel("انتقال به بالا")} disabled={rows.indexOf(r)===0} onClick={()=>move(rows.indexOf(r),-1)}><ArrowUp size={13}/></button><button className="icon-button" aria-label={fieldLabel("انتقال به پایین")} disabled={rows.indexOf(r)===rows.length-1} onClick={()=>move(rows.indexOf(r),1)}><ArrowDown size={13}/></button><button className="icon-button" aria-label={fieldLabel("حذف ردیف")} onClick={()=>onChange(rows.filter(x=>x.id!==r.id))}><Trash2 size={15}/></button></span></div>)}
  <small className="fw-hint">{fieldLabel('عنوان · مقدار · واحد · قیمت واحد · منبع داده')}</small>
 </div>
}
